"""SQLite state store. Every stage persists its output so a crash resumes."""
from __future__ import annotations

import json
import sqlite3
import threading
import time
from contextlib import contextmanager
from typing import Any, Iterator

from .config import DB_PATH

_SCHEMA = """
CREATE TABLE IF NOT EXISTS papers (
  arxiv_id TEXT PRIMARY KEY,
  title TEXT, abstract TEXT, categories TEXT, published TEXT,
  repo_url TEXT, split TEXT, status TEXT DEFAULT 'new',
  verdict TEXT, confidence TEXT, trace_id TEXT,
  created_at REAL, updated_at REAL
);
CREATE TABLE IF NOT EXISTS stages (
  arxiv_id TEXT, stage TEXT, run_label TEXT,
  status TEXT, attempts INTEGER DEFAULT 0,
  output TEXT, error TEXT, started_at REAL, finished_at REAL,
  cost_usd REAL DEFAULT 0, trace_id TEXT,
  PRIMARY KEY (arxiv_id, stage, run_label)
);
CREATE TABLE IF NOT EXISTS sealed_claims (
  arxiv_id TEXT PRIMARY KEY, sha256 TEXT, payload TEXT, created_at REAL
);
CREATE TABLE IF NOT EXISTS spend (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, arxiv_id TEXT, stage TEXT,
  run_label TEXT, model TEXT, prompt_tokens INTEGER, completion_tokens INTEGER,
  cache_read_tokens INTEGER, cache_write_tokens INTEGER, cost_usd REAL
);
CREATE TABLE IF NOT EXISTS failures (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, arxiv_id TEXT, run_label TEXT,
  stage TEXT, category TEXT, detail TEXT, recovered INTEGER DEFAULT 0, trace_id TEXT
);
CREATE TABLE IF NOT EXISTS package_installs (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, arxiv_id TEXT, package TEXT
);
CREATE TABLE IF NOT EXISTS events (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, arxiv_id TEXT, run_label TEXT,
  kind TEXT, payload TEXT
);
"""

_lock = threading.RLock()
_conn: sqlite3.Connection | None = None


def conn() -> sqlite3.Connection:
    global _conn
    if _conn is None:
        DB_PATH.parent.mkdir(parents=True, exist_ok=True)
        _conn = sqlite3.connect(DB_PATH, check_same_thread=False, isolation_level=None)
        _conn.row_factory = sqlite3.Row
        _conn.execute("PRAGMA journal_mode=WAL")
        _conn.executescript(_SCHEMA)
    return _conn


@contextmanager
def tx() -> Iterator[sqlite3.Connection]:
    with _lock:
        c = conn()
        c.execute("BEGIN")
        try:
            yield c
            c.execute("COMMIT")
        except Exception:
            c.execute("ROLLBACK")
            raise


def q(sql: str, args: tuple = ()) -> list[sqlite3.Row]:
    with _lock:
        return conn().execute(sql, args).fetchall()


def q1(sql: str, args: tuple = ()) -> sqlite3.Row | None:
    rows = q(sql, args)
    return rows[0] if rows else None


def ex(sql: str, args: tuple = ()) -> None:
    with _lock:
        conn().execute(sql, args)


def upsert_paper(p: dict[str, Any]) -> bool:
    """Insert a paper if new. Returns True when inserted."""
    now = time.time()
    with tx() as c:
        cur = c.execute(
            "INSERT OR IGNORE INTO papers (arxiv_id,title,abstract,categories,published,repo_url,split,status,created_at,updated_at)"
            " VALUES (?,?,?,?,?,?,?,?,?,?)",
            (p["arxiv_id"], p.get("title"), p.get("abstract"), json.dumps(p.get("categories", [])),
             p.get("published"), p.get("repo_url"), p.get("split"), "new", now, now),
        )
        return cur.rowcount > 0


def set_paper(arxiv_id: str, **fields: Any) -> None:
    if not fields:
        return
    fields["updated_at"] = time.time()
    cols = ",".join(f"{k}=?" for k in fields)
    ex(f"UPDATE papers SET {cols} WHERE arxiv_id=?", (*fields.values(), arxiv_id))


def get_stage(arxiv_id: str, stage: str, run_label: str) -> sqlite3.Row | None:
    return q1("SELECT * FROM stages WHERE arxiv_id=? AND stage=? AND run_label=?", (arxiv_id, stage, run_label))


def save_stage(arxiv_id: str, stage: str, run_label: str, **fields: Any) -> None:
    row = get_stage(arxiv_id, stage, run_label)
    if "output" in fields and not isinstance(fields["output"], (str, type(None))):
        fields["output"] = json.dumps(fields["output"], default=str)
    if row is None:
        fields.setdefault("started_at", time.time())
        cols = ["arxiv_id", "stage", "run_label", *fields.keys()]
        ex(f"INSERT INTO stages ({','.join(cols)}) VALUES ({','.join('?' * len(cols))})",
           (arxiv_id, stage, run_label, *fields.values()))
    else:
        cols = ",".join(f"{k}=?" for k in fields)
        ex(f"UPDATE stages SET {cols} WHERE arxiv_id=? AND stage=? AND run_label=?",
           (*fields.values(), arxiv_id, stage, run_label))


def log_event(arxiv_id: str, run_label: str, kind: str, payload: Any) -> None:
    ex("INSERT INTO events (ts,arxiv_id,run_label,kind,payload) VALUES (?,?,?,?,?)",
       (time.time(), arxiv_id, run_label, kind, json.dumps(payload, default=str)[:20000]))


def log_failure(arxiv_id: str, run_label: str, stage: str, category: str, detail: str,
                recovered: bool = False, trace_id: str | None = None) -> int:
    with tx() as c:
        cur = c.execute(
            "INSERT INTO failures (ts,arxiv_id,run_label,stage,category,detail,recovered,trace_id) VALUES (?,?,?,?,?,?,?,?)",
            (time.time(), arxiv_id, run_label, stage, category, detail[:2000], int(recovered), trace_id))
        return int(cur.lastrowid)


def mark_recovered(failure_id: int) -> None:
    ex("UPDATE failures SET recovered=1 WHERE id=?", (failure_id,))

"""Spend ledger: tokens x price per call, per-paper caps and a global stop."""
from __future__ import annotations

import os
import time

import requests

from . import db
from .config import (DEMO_RESERVE_USD, GLOBAL_BUDGET_USD, HARD_STOP_USD, LITELLM_BASE_URL,
                     PER_PAPER_CAP_USD, PRICES)


class BudgetExceeded(RuntimeError):
    """Raised before a call that would cross a budget line."""


_remote_cache: dict[str, float] = {"ts": 0.0, "spend": 0.0}


def price_call(model: str, prompt_tokens: int, completion_tokens: int,
               cache_read: int = 0, cache_write: int = 0) -> float:
    # Unknown models are priced as the most expensive allowed model (conservative).
    p = PRICES.get(model) or PRICES["claude-sonnet-4.6"]
    uncached = max(prompt_tokens - cache_read - cache_write, 0)
    return (uncached * p["in"] + completion_tokens * p["out"]
            + cache_read * p.get("cache_read", p["in"]) + cache_write * p.get("cache_write", p["in"]))


def record(arxiv_id: str, stage: str, run_label: str, model: str, prompt_tokens: int,
           completion_tokens: int, cache_read: int = 0, cache_write: int = 0) -> float:
    cost = price_call(model, prompt_tokens, completion_tokens, cache_read, cache_write)
    db.ex("INSERT INTO spend (ts,arxiv_id,stage,run_label,model,prompt_tokens,completion_tokens,"
          "cache_read_tokens,cache_write_tokens,cost_usd) VALUES (?,?,?,?,?,?,?,?,?,?)",
          (time.time(), arxiv_id, stage, run_label, model, prompt_tokens, completion_tokens,
           cache_read, cache_write, cost))
    return cost


def local_total() -> float:
    r = db.q1("SELECT COALESCE(SUM(cost_usd),0) AS s FROM spend")
    return float(r["s"]) if r else 0.0


def paper_total(arxiv_id: str, run_label: str | None = None, stage: str | None = None) -> float:
    sql, args = "SELECT COALESCE(SUM(cost_usd),0) AS s FROM spend WHERE arxiv_id=?", [arxiv_id]
    if run_label:
        sql += " AND run_label=?"; args.append(run_label)
    if stage:
        sql += " AND stage=?"; args.append(stage)
    r = db.q1(sql, tuple(args))
    return float(r["s"]) if r else 0.0


def remote_spend(max_age: float = 300.0) -> float:
    """Authoritative spend reported by the LiteLLM proxy for this key."""
    if time.time() - _remote_cache["ts"] < max_age:
        return _remote_cache["spend"]
    base = LITELLM_BASE_URL.rstrip("/")
    base = base[:-3] if base.endswith("/v1") else base
    try:
        r = requests.get(f"{base}/key/info", timeout=15,
                         headers={"Authorization": "Bearer " + os.environ["LITELLM_API_KEY"]})
        r.raise_for_status()
        _remote_cache.update(ts=time.time(), spend=float(r.json()["info"].get("spend") or 0.0))
    except Exception:
        _remote_cache["ts"] = time.time()
    return _remote_cache["spend"]


def global_spend() -> float:
    return max(local_total(), remote_spend())


def precheck(arxiv_id: str, run_label: str, est_cost: float, stage_cap: float | None = None,
             stage: str | None = None, allow_reserve: bool = False) -> None:
    spent = global_spend()
    limit = min(HARD_STOP_USD, GLOBAL_BUDGET_USD - (0 if allow_reserve else DEMO_RESERVE_USD))
    if spent + est_cost > limit:
        raise BudgetExceeded(f"global spend {spent:.3f}+{est_cost:.3f} > limit {limit:.2f}")
    if arxiv_id and arxiv_id != "-":
        p = paper_total(arxiv_id, run_label)
        if p + est_cost > PER_PAPER_CAP_USD:
            raise BudgetExceeded(f"paper spend {p:.3f}+{est_cost:.3f} > cap {PER_PAPER_CAP_USD:.2f}")
        if stage_cap is not None and stage:
            s = paper_total(arxiv_id, run_label, stage)
            if s + est_cost > stage_cap:
                raise BudgetExceeded(f"stage {stage} spend {s:.3f}+{est_cost:.3f} > cap {stage_cap:.2f}")


def summary() -> dict:
    rows = db.q("SELECT stage, model, COUNT(*) n, SUM(prompt_tokens) pt, SUM(completion_tokens) ct, "
                "SUM(cost_usd) c FROM spend GROUP BY stage, model ORDER BY c DESC")
    return {"local_total": local_total(), "remote_total": remote_spend(0),
            "by_stage_model": [dict(r) for r in rows]}

"""neatlogs setup. One WORKFLOW root per paper, one CHAIN/AGENT span per stage."""
from __future__ import annotations

import json
import os
from contextlib import contextmanager
from typing import Any, Iterator

import neatlogs
from opentelemetry import trace as otel_trace

_initialized = False


def init(run_label: str, variant: str) -> None:
    global _initialized
    if _initialized:
        return
    neatlogs.init(
        api_key=os.environ.get("NEATLOGS_API_KEY"),
        endpoint=os.environ.get("NEATLOGS_ENDPOINT", "https://ingest.neatlogs.com"),
        workflow_name="paperci-reproduce-paper",
        tags=["paperci", f"run:{run_label}", f"variant:{variant}"],
        capture_logs=True,
        flush_interval=2.0,
    )
    _initialized = True


def shutdown() -> None:
    if _initialized:
        neatlogs.flush()
        neatlogs.shutdown()


def current_trace_id() -> str | None:
    ctx = otel_trace.get_current_span().get_span_context()
    return format(ctx.trace_id, "032x") if ctx and ctx.trace_id else None


def _safe(v: Any) -> Any:
    if isinstance(v, (str, int, float, bool)):
        return v
    return json.dumps(v, default=str)[:4000]


@contextmanager
def span(name: str, kind: str = "CHAIN", **attrs: Any) -> Iterator[Any]:
    """Open a span; attributes are stamped as paperci.<key>."""
    with neatlogs.trace(name, kind=kind) as s:
        for k, v in attrs.items():
            set_attr(s, k, v)
        yield s


def set_attr(s: Any, key: str, value: Any) -> None:
    try:
        s.set_attribute(f"paperci.{key}", _safe(value))
    except Exception:
        pass


def log(msg: str, level: str = "info", **data: Any) -> None:
    try:
        neatlogs.log(msg, level=level, **{k: _safe(v) for k, v in data.items()})
    except Exception:
        pass

